import{_ as a,o as r,c as d,a3 as e}from"./chunks/framework.B5WAEDB7.js";const b=JSON.parse('{"title":"系统概述","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md","lastUpdated":1786258579000}'),n={name:"overview.md"};function o(i,t,h,l,s,c){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="系统概述" tabindex="-1">系统概述 <a class="header-anchor" href="#系统概述" aria-label="Permalink to &quot;系统概述&quot;">​</a></h1><p>XiHan.BasicApp 是一个<strong>企业级中后台内核</strong>：后端基于 .NET 10 与 <a href="https://framework.docs.xihanfun.com/" target="_blank" rel="noreferrer">XiHan.Framework</a>，前端基于 Vue 3。它把中后台系统里&quot;每个项目都要重做一遍&quot;的部分——身份、权限、租户、审计、代码生成、实时通信——一次性做好，让你专注在真正的业务上。</p><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>面向生产的中后台起点</strong>：提供 RBAC + ABAC、多租户与审计等基础能力，上线前仍需完成安全配置、容量验证与业务适配</li><li><strong>全栈实践参考</strong>：一套规范的 .NET + Vue 前后端分离工程，从契约到 UI 数据流都可借鉴</li><li><strong>框架用法样板</strong>：XiHan.Framework 各能力在真实业务里怎么用，这里有活的例子</li></ul><h2 id="架构风格" tabindex="-1">架构风格 <a class="header-anchor" href="#架构风格" aria-label="Permalink to &quot;架构风格&quot;">​</a></h2><p>系统采用<strong>前后端分离</strong>：</p><ul><li><strong>后端</strong>遵循 DDD 分层与 CQRS，应用服务经<strong>动态 API</strong> 直接暴露为 REST 接口——不写 Controller，接口即服务方法</li><li><strong>前端</strong>使用 Vue 3 + TypeScript + Naive UI，列表页由 <strong>Schema 驱动</strong>，搜索/表格/导出按配置生成，并对权限、租户、个人偏好三重感知</li></ul><p>详见 <a href="./backend/introduction">系统架构</a>。</p><h2 id="能力全景" tabindex="-1">能力全景 <a class="header-anchor" href="#能力全景" aria-label="Permalink to &quot;能力全景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>领域</th><th>关键能力</th></tr></thead><tbody><tr><td><a href="./backend/authentication">身份与认证</a></td><td>用户/角色/菜单；JWT 双令牌；账号密码、邮箱/短信验证码、OAuth2（GitHub/Gitee/Google/QQ）、2FA</td></tr><tr><td><a href="./backend/permission">权限</a></td><td>RBAC + ABAC，权限码 <code>module:resource:action</code>（如 <code>saas:user:read</code>），数据范围，字段级脱敏，会话角色激活</td></tr><tr><td><a href="./backend/organization">组织架构</a></td><td>部门树 + 闭包表、岗位字典、用户多部门归属（数据范围的底座）</td></tr><tr><td><a href="./backend/multi-tenancy">多租户</a></td><td>字段级隔离，邮箱全局唯一登录，租户版本（Edition）权限白名单门控</td></tr><tr><td><a href="./backend/messaging">消息中心</a></td><td>五类消息 + 优先级 + 强制阅读；模板；四渠道扇出；SignalR 通知与在线聊天</td></tr><tr><td><a href="./backend/workflow">工作流</a></td><td>图执行引擎、17 个内置活动、人工任务（或签/会签/依次）、落库可恢复</td></tr><tr><td><a href="./backend/approval">审批与约束</a></td><td>通用审批单 <code>SysReview</code>；RBAC 约束规则引擎（SSD/DSD/互斥/基数…八类）</td></tr><tr><td><a href="./backend/file">文件与存储</a></td><td>元数据与存储位置分离、多后端（本地/S3/OSS/COS/MinIO）、异步导出中心</td></tr><tr><td><a href="./backend/scheduling">任务调度</a></td><td>Cron/间隔/一次性触发、并发控制、多租户上下文、按月分表日志</td></tr><tr><td><a href="./backend/settings">系统设置</a></td><td>菜单、字典、参数、业务编号、缓存、服务监控、版本、通道配置</td></tr><tr><td><a href="./backend/health-observability">健康与可观测性</a></td><td>数据库/Redis/Qdrant 健康检查，TraceId，OpenTelemetry 链路与指标导出</td></tr><tr><td><a href="./backend/upgrade">升级与迁移</a></td><td>前向 SQL、版本/迁移台账、租约锁、多租户升级与维护模式；执行入口状态说明</td></tr><tr><td><a href="./backend/open-api">开放能力</a></td><td>OAuth2/OIDC 服务端、开放接口签名调用、个人 API 凭证</td></tr><tr><td><a href="./backend/logging">审计日志</a></td><td>访问/API/操作/异常/登录/实体变更等多类日志，落库前自动脱敏</td></tr><tr><td><a href="./backend/code-generation">代码生成</a></td><td>单表/树形/主从三模式，实体→DTO→API→前端页一键生成，Scriban 模板</td></tr><tr><td><a href="./backend/ai">AI 能力</a></td><td>Provider 库化管理（热切换）、RAG 知识库（Qdrant）、Agent / MCP</td></tr><tr><td><a href="./frontend/introduction">前端体验</a></td><td>Schema 驱动列表、命令面板、多标签、消息中心、偏好中心、富文本、时区切换</td></tr></tbody></table><p>完整清单见 <a href="./features">功能清单</a>。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><h3 id="后端" tabindex="-1">后端 <a class="header-anchor" href="#后端" aria-label="Permalink to &quot;后端&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技术</th><th>说明</th></tr></thead><tbody><tr><td>.NET 10 / C#</td><td>运行时与语言</td></tr><tr><td>XiHan.Framework 3.10.1</td><td>自研模块化应用框架</td></tr><tr><td>SqlSugar</td><td>ORM，支持 PostgreSQL / MySQL / MariaDB</td></tr><tr><td>Redis</td><td>分布式缓存与分布式锁</td></tr><tr><td>SignalR</td><td>实时通信</td></tr><tr><td>Serilog</td><td>结构化日志</td></tr><tr><td>Scalar</td><td>API 文档</td></tr></tbody></table><h3 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技术</th><th>说明</th></tr></thead><tbody><tr><td>Vue 3.5+</td><td>UI 框架</td></tr><tr><td>TypeScript 6.0+</td><td>类型系统</td></tr><tr><td>Vite 8</td><td>构建工具</td></tr><tr><td>Naive UI</td><td>组件库</td></tr><tr><td>Pinia</td><td>状态管理</td></tr><tr><td>Tailwind CSS 4</td><td>原子化 CSS</td></tr><tr><td>Tiptap</td><td>富文本编辑器</td></tr><tr><td>vue-i18n</td><td>国际化</td></tr></tbody></table><h2 id="文档怎么读" tabindex="-1">文档怎么读 <a class="header-anchor" href="#文档怎么读" aria-label="Permalink to &quot;文档怎么读&quot;">​</a></h2><p>按角色挑一条线走：</p><table tabindex="0"><thead><tr><th>你是</th><th>推荐路线</th></tr></thead><tbody><tr><td><strong>第一次接触</strong></td><td><a href="./dev-environment">开发环境</a> → <a href="./getting-started">快速开始</a> → <a href="./project-structure">目录结构与代码地图</a></td></tr><tr><td><strong>后端开发</strong></td><td><a href="./backend/introduction">架构总览</a> → <a href="./backend/introduction">后端架构</a> → <a href="./backend/request-lifecycle">请求生命周期</a> → <a href="./backend/data-model">数据模型</a> → <a href="./backend/development">二次开发</a></td></tr><tr><td><strong>前端开发</strong></td><td><a href="./frontend/introduction">前端架构</a> → <a href="./frontend/introduction">前端开发指南</a> → <a href="./frontend/schema-page">Schema 驱动页面</a></td></tr><tr><td><strong>对接接口</strong></td><td><a href="./api-guide">接口对接指南</a>（含<strong>怎么获取 token</strong>）</td></tr><tr><td><strong>运维部署</strong></td><td><a href="./configuration">配置参考</a> → <a href="./deployment">部署</a></td></tr><tr><td><strong>排查问题</strong></td><td><a href="./faq">常见问题</a> → <a href="./backend/request-lifecycle#按现象定位">请求生命周期</a></td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./dev-environment">开发环境</a>：用 Docker 命令行准备数据库与 Redis 等本地依赖</li><li><a href="./getting-started">快速开始</a>：在本地把系统跑起来</li><li><a href="./backend/introduction">架构总览</a>：全景与五个架构分册的索引</li><li><a href="./backend/permission">权限模型</a>：RBAC + ABAC 与多租户隔离</li></ul>',21)])])}const u=a(n,[["render",o]]);export{b as __pageData,u as default};
